// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./RWASynth.sol";

/// @title  AchRWAOracle
/// @notice Central registry and price oracle for AchRWA Protocol.
///         Owner creates RWA pairs and manages authorized price submitters.
///         Submitters push prices every ~1 minute via submitPriceBatch.
///         All price data is public — external builders can read from this contract.
///         60-slot ring buffer stores 1 hour of price history per pair.
contract AchRWAOracle {

    uint256 public  constant MAX_PAIRS     = 200;
    uint256 public  constant HISTORY_SIZE  = 60;
    uint256 public  constant MIN_STALENESS = 60;
    uint256 public  constant MAX_DEVIATION = 10_000;
    uint256 private constant BPS_DENOM    = 10_000;

    enum Category { Stock, Commodity, Forex }

    struct RWAPair {
        uint256  pairId;
        string   name;
        string   symbol;
        Category category;
        string   priceSource;
        string   description;
        address  synth;
        uint256  price;
        uint256  lastUpdated;
        uint256  maxStaleness;
        uint256  maxDeviation;
        bool     active;
        bool     frozen;
        uint256  createdAt;
    }

    struct PricePoint {
        uint256 price;
        uint256 timestamp;
        address submitter;
    }

    struct SubmitterInfo {
        address addr;
        bool    authorized;
        uint256 totalSubmissions;
        uint256 lastSubmission;
    }

    address public owner;
    address public pendingOwner;
    address public vault;

    bool    public paused;
    uint256 public pairCount;
    uint256 public totalPriceUpdates;

    mapping(uint256 => RWAPair)        private _pairs;
    mapping(string  => uint256)        private _symbolToId;
    mapping(address => bool)           public  isSubmitter;
    mapping(address => uint256)        public  submitterTotalUpdates;
    mapping(address => uint256)        public  submitterLastUpdate;
    mapping(uint256 => PricePoint[60]) private _history;
    mapping(uint256 => uint256)        private _historyHead;

    address[] private _submitterList;

    event PairCreated(
        uint256  indexed pairId,
        string           name,
        string           symbol,
        Category indexed category,
        address          synth,
        uint256          maxStaleness,
        uint256          maxDeviation,
        uint256          timestamp
    );

    event PriceSubmitted(
        uint256 indexed pairId,
        string          symbol,
        uint256         price,
        uint256         previousPrice,
        int256          delta,
        address indexed submitter,
        uint256         timestamp
    );

    event PriceSkipped(
        uint256 indexed pairId,
        address indexed submitter,
        string          reason,
        uint256         timestamp
    );

    event PairMetaUpdated(uint256 indexed pairId, uint256 timestamp);
    event PairActiveSet  (uint256 indexed pairId, bool active, uint256 timestamp);
    event PairFrozenSet  (uint256 indexed pairId, bool frozen, uint256 timestamp);
    event SubmitterAdded  (address indexed submitter, uint256 timestamp);
    event SubmitterRemoved(address indexed submitter, uint256 timestamp);
    event VaultSet        (address indexed vault,     uint256 timestamp);
    event Paused          (address indexed by,        uint256 timestamp);
    event Unpaused        (address indexed by,        uint256 timestamp);
    event OwnershipTransferInitiated(address indexed newOwner, uint256 timestamp);
    event OwnershipTransferred(address indexed oldOwner, address indexed newOwner, uint256 timestamp);

    constructor() {
        owner = msg.sender;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "AchRWAOracle: not owner");
        _;
    }

    modifier onlySubmitter() {
        require(isSubmitter[msg.sender], "AchRWAOracle: not authorized submitter");
        _;
    }

    modifier whenNotPaused() {
        require(!paused, "AchRWAOracle: protocol paused");
        _;
    }

    modifier pairExists(uint256 pairId) {
        require(pairId > 0 && pairId <= pairCount, "AchRWAOracle: pair not found");
        _;
    }

    // Ownership

    /// @notice Step 1 of two-step ownership transfer.
    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "AchRWAOracle: zero address");
        pendingOwner = newOwner;
        emit OwnershipTransferInitiated(newOwner, block.timestamp);
    }

    /// @notice Step 2 — new owner accepts. Prevents accidental lockout.
    function acceptOwnership() external {
        require(msg.sender == pendingOwner, "AchRWAOracle: not pending owner");
        emit OwnershipTransferred(owner, pendingOwner, block.timestamp);
        owner        = pendingOwner;
        pendingOwner = address(0);
    }

    // Vault

    /// @notice Set vault once. Immutable after first call.
    function setVault(address _vault) external onlyOwner {
        require(_vault != address(0), "AchRWAOracle: zero vault");
        require(vault  == address(0), "AchRWAOracle: vault already set");
        vault = _vault;
        emit VaultSet(_vault, block.timestamp);
    }

    // Emergency

    function pause() external onlyOwner {
        require(!paused, "AchRWAOracle: already paused");
        paused = true;
        emit Paused(msg.sender, block.timestamp);
    }

    function unpause() external onlyOwner {
        require(paused, "AchRWAOracle: not paused");
        paused = false;
        emit Unpaused(msg.sender, block.timestamp);
    }

    /// @notice Freeze price updates for one pair without affecting others.
    function setFrozen(uint256 pairId, bool frozen) external onlyOwner pairExists(pairId) {
        _pairs[pairId].frozen = frozen;
        emit PairFrozenSet(pairId, frozen, block.timestamp);
    }

    // Submitters

    function addSubmitter(address submitter) external onlyOwner {
        require(submitter        != address(0), "AchRWAOracle: zero address");
        require(!isSubmitter[submitter],        "AchRWAOracle: already submitter");
        isSubmitter[submitter] = true;
        _submitterList.push(submitter);
        emit SubmitterAdded(submitter, block.timestamp);
    }

    function removeSubmitter(address submitter) external onlyOwner {
        require(isSubmitter[submitter], "AchRWAOracle: not a submitter");
        isSubmitter[submitter] = false;
        emit SubmitterRemoved(submitter, block.timestamp);
    }

    // Pair management

    /// @notice Create a new RWA pair. Deploys a RWASynth ERC20 automatically.
    /// @param _maxStaleness Seconds before price is stale. Min 60. Recommended 90 for 1min oracle.
    /// @param _maxDeviation Max % price change per submission in BPS. e.g. 5000 = 50%.
    function createPair(
        string   memory _name,
        string   memory _symbol,
        Category        _category,
        string   memory _priceSource,
        string   memory _description,
        uint256         _maxStaleness,
        uint256         _maxDeviation
    ) external onlyOwner returns (uint256 pairId) {
        require(vault != address(0),            "AchRWAOracle: vault not set");
        require(bytes(_name).length        > 0, "AchRWAOracle: empty name");
        require(bytes(_symbol).length      > 0, "AchRWAOracle: empty symbol");
        require(bytes(_priceSource).length > 0, "AchRWAOracle: empty priceSource");
        require(_symbolToId[_symbol]       == 0,"AchRWAOracle: symbol already exists");
        require(_maxStaleness >= MIN_STALENESS, "AchRWAOracle: staleness too low");
        require(
            _maxDeviation > 0 && _maxDeviation <= MAX_DEVIATION,
            "AchRWAOracle: deviation out of range"
        );
        require(pairCount < MAX_PAIRS, "AchRWAOracle: max pairs reached");

        pairId = ++pairCount;

        RWASynth synth = new RWASynth(
            string(abi.encodePacked("Synth ", _name)),
            _symbol,
            vault,
            address(this)
        );

        _pairs[pairId] = RWAPair({
            pairId:       pairId,
            name:         _name,
            symbol:       _symbol,
            category:     _category,
            priceSource:  _priceSource,
            description:  _description,
            synth:        address(synth),
            price:        0,
            lastUpdated:  0,
            maxStaleness: _maxStaleness,
            maxDeviation: _maxDeviation,
            active:       true,
            frozen:       false,
            createdAt:    block.timestamp
        });

        _symbolToId[_symbol] = pairId;

        emit PairCreated(
            pairId, _name, _symbol, _category,
            address(synth), _maxStaleness, _maxDeviation, block.timestamp
        );
    }

    /// @notice Update pair metadata. Symbol and synth address cannot be changed.
    function updatePairMeta(
        uint256       pairId,
        string memory _name,
        string memory _priceSource,
        string memory _description,
        uint256       _maxStaleness,
        uint256       _maxDeviation
    ) external onlyOwner pairExists(pairId) {
        RWAPair storage p = _pairs[pairId];
        if (bytes(_name).length        > 0)                      p.name         = _name;
        if (bytes(_priceSource).length > 0)                      p.priceSource  = _priceSource;
        if (bytes(_description).length > 0)                      p.description  = _description;
        if (_maxStaleness >= MIN_STALENESS)                       p.maxStaleness = _maxStaleness;
        if (_maxDeviation > 0 && _maxDeviation <= MAX_DEVIATION)  p.maxDeviation = _maxDeviation;
        emit PairMetaUpdated(pairId, block.timestamp);
    }

    function setPairActive(uint256 pairId, bool active) external onlyOwner pairExists(pairId) {
        _pairs[pairId].active = active;
        emit PairActiveSet(pairId, active, block.timestamp);
    }

    // Price submission

    /// @notice Submit a single price. Price in 18 dec USD. e.g. $189.50 = 189500000000000000000
    function submitPrice(uint256 pairId, uint256 price)
        external
        onlySubmitter
        whenNotPaused
        pairExists(pairId)
    {
        _submitPrice(pairId, price);
    }

    /// @notice Batch submit for all pairs in one tx. Call every minute from keeper.
    ///         Inactive, frozen, or invalid pairs are skipped — batch never reverts.
    function submitPriceBatch(
        uint256[] calldata pairIds,
        uint256[] calldata prices
    ) external onlySubmitter whenNotPaused {
        require(pairIds.length == prices.length, "AchRWAOracle: length mismatch");
        require(pairIds.length > 0,              "AchRWAOracle: empty batch");
        require(pairIds.length <= MAX_PAIRS,     "AchRWAOracle: batch too large");

        bool[] memory seen = new bool[](pairCount + 1);

        for (uint256 i = 0; i < pairIds.length; i++) {
            uint256 pid   = pairIds[i];
            uint256 price = prices[i];

            if (pid == 0 || pid > pairCount) {
                emit PriceSkipped(pid, msg.sender, "invalid pairId", block.timestamp);
                continue;
            }

            if (seen[pid]) {
                emit PriceSkipped(pid, msg.sender, "duplicate in batch", block.timestamp);
                continue;
            }
            seen[pid] = true;

            if (price == 0) {
                emit PriceSkipped(pid, msg.sender, "zero price", block.timestamp);
                continue;
            }

            RWAPair storage p = _pairs[pid];

            if (!p.active) {
                emit PriceSkipped(pid, msg.sender, "pair not active", block.timestamp);
                continue;
            }

            if (p.frozen) {
                emit PriceSkipped(pid, msg.sender, "pair frozen", block.timestamp);
                continue;
            }

            if (p.price > 0) {
                uint256 prev = p.price;
                uint256 diff = price > prev ? price - prev : prev - price;
                if (diff * BPS_DENOM > prev * p.maxDeviation) {
                    emit PriceSkipped(pid, msg.sender, "deviation too high", block.timestamp);
                    continue;
                }
            }

            _writePriceToStorage(pid, price);
        }
    }

    function _submitPrice(uint256 pairId, uint256 price) internal {
        require(price > 0, "AchRWAOracle: zero price");
        RWAPair storage p = _pairs[pairId];
        require(p.active,  "AchRWAOracle: pair not active");
        require(!p.frozen, "AchRWAOracle: pair is frozen");

        if (p.price > 0) {
            uint256 prev = p.price;
            uint256 diff = price > prev ? price - prev : prev - price;
            require(
                diff * BPS_DENOM <= prev * p.maxDeviation,
                "AchRWAOracle: price deviation too high"
            );
        }

        _writePriceToStorage(pairId, price);
    }

    function _writePriceToStorage(uint256 pairId, uint256 price) internal {
        RWAPair storage p = _pairs[pairId];

        uint256 previousPrice = p.price;
        int256  delta         = int256(price) - int256(previousPrice);

        uint256 head = _historyHead[pairId];
        _history[pairId][head] = PricePoint({
            price:     price,
            timestamp: block.timestamp,
            submitter: msg.sender
        });
        _historyHead[pairId] = (head + 1) % HISTORY_SIZE;

        p.price       = price;
        p.lastUpdated = block.timestamp;

        submitterTotalUpdates[msg.sender]++;
        submitterLastUpdate[msg.sender] = block.timestamp;
        totalPriceUpdates++;

        emit PriceSubmitted(
            pairId, p.symbol, price, previousPrice,
            delta, msg.sender, block.timestamp
        );
    }

    // View — single pair

    function getPair(uint256 pairId) external view pairExists(pairId) returns (RWAPair memory) {
        return _pairs[pairId];
    }

    function getPairBySymbol(string memory symbol) external view returns (RWAPair memory) {
        uint256 pid = _symbolToId[symbol];
        require(pid != 0, "AchRWAOracle: symbol not found");
        return _pairs[pid];
    }

    function getPairId(string memory symbol) external view returns (uint256) {
        uint256 pid = _symbolToId[symbol];
        require(pid != 0, "AchRWAOracle: symbol not found");
        return pid;
    }

    /// @notice Live price with staleness info.
    /// @return price       Current price (18 dec). 0 if never submitted.
    /// @return lastUpdated Timestamp of last push.
    /// @return age         Seconds since last update. max uint256 if never set.
    /// @return isStale     True if age > maxStaleness or never submitted.
    function getPrice(uint256 pairId) external view pairExists(pairId)
        returns (uint256 price, uint256 lastUpdated, uint256 age, bool isStale)
    {
        RWAPair storage p = _pairs[pairId];
        if (p.lastUpdated == 0) return (0, 0, type(uint256).max, true);
        age     = block.timestamp - p.lastUpdated;
        isStale = age > p.maxStaleness;
        return (p.price, p.lastUpdated, age, isStale);
    }

    function getPriceSource(uint256 pairId) external view pairExists(pairId) returns (string memory) {
        return _pairs[pairId].priceSource;
    }

    function isPriceFresh(uint256 pairId) external view pairExists(pairId) returns (bool) {
        RWAPair storage p = _pairs[pairId];
        if (p.lastUpdated == 0) return false;
        return (block.timestamp - p.lastUpdated) <= p.maxStaleness;
    }

    // View — batch

    function getAllPairs() external view returns (RWAPair[] memory result) {
        result = new RWAPair[](pairCount);
        for (uint256 i = 1; i <= pairCount; i++) result[i - 1] = _pairs[i];
    }

    function getActivePairs() external view returns (RWAPair[] memory) {
        uint256 count = 0;
        for (uint256 i = 1; i <= pairCount; i++) { if (_pairs[i].active) count++; }
        RWAPair[] memory result = new RWAPair[](count);
        uint256 j = 0;
        for (uint256 i = 1; i <= pairCount; i++) { if (_pairs[i].active) result[j++] = _pairs[i]; }
        return result;
    }

    function getPairsByCategory(Category category) external view returns (RWAPair[] memory) {
        uint256 count = 0;
        for (uint256 i = 1; i <= pairCount; i++) {
            if (_pairs[i].active && _pairs[i].category == category) count++;
        }
        RWAPair[] memory result = new RWAPair[](count);
        uint256 j = 0;
        for (uint256 i = 1; i <= pairCount; i++) {
            if (_pairs[i].active && _pairs[i].category == category) result[j++] = _pairs[i];
        }
        return result;
    }

    function getLatestPrices(uint256[] calldata pairIds) external view
        returns (uint256[] memory prices, uint256[] memory ages, bool[] memory staleFlags)
    {
        uint256 n  = pairIds.length;
        prices     = new uint256[](n);
        ages       = new uint256[](n);
        staleFlags = new bool[](n);

        for (uint256 i = 0; i < n; i++) {
            uint256 pid = pairIds[i];
            if (pid == 0 || pid > pairCount) {
                staleFlags[i] = true;
                ages[i]       = type(uint256).max;
                continue;
            }
            RWAPair storage p = _pairs[pid];
            prices[i] = p.price;
            if (p.lastUpdated == 0) {
                ages[i]       = type(uint256).max;
                staleFlags[i] = true;
            } else {
                ages[i]       = block.timestamp - p.lastUpdated;
                staleFlags[i] = ages[i] > p.maxStaleness;
            }
        }
    }

    function getAllActivePrices() external view
        returns (
            uint256[] memory pairIds,
            string[]  memory symbols,
            uint256[] memory prices,
            uint256[] memory ages,
            bool[]    memory staleFlags
        )
    {
        uint256 count = 0;
        for (uint256 i = 1; i <= pairCount; i++) { if (_pairs[i].active) count++; }

        pairIds    = new uint256[](count);
        symbols    = new string[] (count);
        prices     = new uint256[](count);
        ages       = new uint256[](count);
        staleFlags = new bool[]   (count);

        uint256 j = 0;
        for (uint256 i = 1; i <= pairCount; i++) {
            if (!_pairs[i].active) continue;
            RWAPair storage p = _pairs[i];
            pairIds[j] = i;
            symbols[j] = p.symbol;
            prices[j]  = p.price;
            if (p.lastUpdated == 0) {
                ages[j]       = type(uint256).max;
                staleFlags[j] = true;
            } else {
                ages[j]       = block.timestamp - p.lastUpdated;
                staleFlags[j] = ages[j] > p.maxStaleness;
            }
            j++;
        }
    }

    // View — price history

    /// @notice Last 60 price points for a pair. Newest first.
    function getPriceHistory(uint256 pairId) external view pairExists(pairId)
        returns (PricePoint[] memory history)
    {
        PricePoint[60] storage raw  = _history[pairId];
        uint256        writeHead    = _historyHead[pairId];

        uint256 count = 0;
        for (uint256 i = 0; i < HISTORY_SIZE; i++) {
            if (raw[i].timestamp != 0) count++;
        }
        if (count == 0) return new PricePoint[](0);

        history = new PricePoint[](count);
        uint256 j = 0;
        for (uint256 k = 0; k < HISTORY_SIZE && j < count; k++) {
            uint256 idx = (writeHead + HISTORY_SIZE - 1 - k) % HISTORY_SIZE;
            if (raw[idx].timestamp != 0) history[j++] = raw[idx];
        }
    }

    function getLatestPricePoint(uint256 pairId) external view pairExists(pairId)
        returns (PricePoint memory)
    {
        uint256 head = _historyHead[pairId];
        uint256 last = (head + HISTORY_SIZE - 1) % HISTORY_SIZE;
        return _history[pairId][last];
    }

    // View — submitters

    function getAllSubmitters() external view returns (SubmitterInfo[] memory result) {
        result = new SubmitterInfo[](_submitterList.length);
        for (uint256 i = 0; i < _submitterList.length; i++) {
            address s = _submitterList[i];
            result[i] = SubmitterInfo({
                addr:             s,
                authorized:       isSubmitter[s],
                totalSubmissions: submitterTotalUpdates[s],
                lastSubmission:   submitterLastUpdate[s]
            });
        }
    }

    // View — protocol snapshot

    function getProtocolStats() external view returns (
        uint256 _pairCount,
        uint256 _activePairCount,
        uint256 _totalPriceUpdates,
        uint256 _submitterCount,
        address _owner,
        address _vault,
        bool    _paused
    ) {
        uint256 activeCount = 0;
        for (uint256 i = 1; i <= pairCount; i++) {
            if (_pairs[i].active) activeCount++;
        }
        return (pairCount, activeCount, totalPriceUpdates, _submitterList.length, owner, vault, paused);
    }

    /// @notice Check if a price is safe to use. Useful for external contracts.
    function canUsePrice(uint256 pairId) external view returns (
        bool          usable,
        uint256       price,
        string memory reason
    ) {
        if (pairId == 0 || pairId > pairCount) return (false, 0, "pair not found");
        if (paused)                             return (false, 0, "protocol paused");
        RWAPair storage p = _pairs[pairId];
        if (!p.active)                          return (false, 0, "pair not active");
        if (p.frozen)                           return (false, 0, "pair frozen");
        if (p.price == 0)                       return (false, 0, "no price submitted yet");
        if (p.lastUpdated == 0)                 return (false, 0, "never updated");
        uint256 age = block.timestamp - p.lastUpdated;
        if (age > p.maxStaleness)               return (false, p.price, "price stale");
        return (true, p.price, "ok");
    }

    receive()  external payable { revert("AchRWAOracle: does not accept native tokens"); }
    fallback() external payable { revert("AchRWAOracle: function not found"); }
}

