// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title  RWASynth
/// @notice ERC20 synthetic token for a real-world asset. Deployed by AchRWAOracle.
///         Only the vault can mint or burn. 18 decimals matches Arc native USDC.
contract RWASynth {

    string  public name;
    string  public symbol;
    uint8   public constant decimals = 18;
    uint256 public totalSupply;

    mapping(address => uint256)                     public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    /// @notice Immutable vault address — only caller allowed to mint and burn.
    address public immutable vault;
    /// @notice Immutable oracle address — registry that deployed this synth.
    address public immutable oracle;

    event Transfer(address indexed from,  address indexed to,      uint256 amount);
    event Approval(address indexed owner, address indexed spender, uint256 amount);
    event Minted  (address indexed to,    uint256 amount, uint256 newTotalSupply);
    event Burned  (address indexed from,  uint256 amount, uint256 newTotalSupply);

    constructor(
        string memory _name,
        string memory _symbol,
        address       _vault,
        address       _oracle
    ) {
        require(bytes(_name).length   > 0, "RWASynth: empty name");
        require(bytes(_symbol).length > 0, "RWASynth: empty symbol");
        require(_vault  != address(0),     "RWASynth: zero vault");
        require(_oracle != address(0),     "RWASynth: zero oracle");
        name   = _name;
        symbol = _symbol;
        vault  = _vault;
        oracle = _oracle;
    }

    modifier onlyVault() {
        require(msg.sender == vault, "RWASynth: caller is not vault");
        _;
    }

    /// @notice Mint tokens to `to`. Called by vault on buy.
    function mint(address to, uint256 amount) external onlyVault {
        require(to     != address(0), "RWASynth: mint to zero address");
        require(amount >  0,          "RWASynth: zero amount");
        totalSupply   += amount;
        balanceOf[to] += amount;
        emit Transfer(address(0), to, amount);
        emit Minted(to, amount, totalSupply);
    }

    /// @notice Burn tokens from `from`. Called by vault on redeem.
    ///         No allowance consumed — vault is the trusted burner, not a spender.
    function burn(address from, uint256 amount) external onlyVault {
        require(from   != address(0),      "RWASynth: burn from zero address");
        require(amount >  0,               "RWASynth: zero amount");
        require(balanceOf[from] >= amount, "RWASynth: burn exceeds balance");
        balanceOf[from] -= amount;
        totalSupply     -= amount;
        emit Transfer(from, address(0), amount);
        emit Burned(from, amount, totalSupply);
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        require(to                    != address(0), "RWASynth: transfer to zero");
        require(balanceOf[msg.sender] >= amount,     "RWASynth: insufficient balance");
        unchecked {
            balanceOf[msg.sender] -= amount;
            balanceOf[to]         += amount;
        }
        emit Transfer(msg.sender, to, amount);
        return true;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        require(spender != address(0), "RWASynth: approve to zero");
        allowance[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(from   != address(0),                  "RWASynth: transfer from zero");
        require(to     != address(0),                  "RWASynth: transfer to zero");
        require(balanceOf[from]             >= amount, "RWASynth: insufficient balance");
        require(allowance[from][msg.sender] >= amount, "RWASynth: insufficient allowance");
        if (allowance[from][msg.sender] != type(uint256).max) {
            allowance[from][msg.sender] -= amount;
        }
        unchecked {
            balanceOf[from] -= amount;
            balanceOf[to]   += amount;
        }
        emit Transfer(from, to, amount);
        return true;
    }

    /// @notice All token metadata in one call.
    function tokenInfo() external view returns (
        string memory _name,
        string memory _symbol,
        uint8         _decimals,
        uint256       _totalSupply,
        address       _vault,
        address       _oracle
    ) {
        return (name, symbol, decimals, totalSupply, vault, oracle);
    }

    /// @notice Balance and allowance for a holder/spender pair.
    function balanceAndAllowance(address holder, address spender) external view returns (
        uint256 balance,
        uint256 _allowance
    ) {
        return (balanceOf[holder], allowance[holder][spender]);
    }
}
